            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下皆知美之为美，斯恶已；皆知善之为善，斯不善矣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "有无相生，难易相成，长短相形，高下相盈，音声相和，前后相随。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人处无为之事，行不言之教。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "万物作，焉而弗辞，生而弗有，为而弗恃，功成而弗居。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯弗居，是以不去。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "不尚贤使民不争；不贵难得之货使民不为盗；不见可欲使民心不乱。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人之治：虚其心，实其腹；弱其志，强其骨。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "常使民无知无欲。使夫知者不敢为也。为无为，则无不治。", Author = "老子" },
