            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "挫其锐，解其纷；和其光，同其尘。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天地不仁，以万物为刍狗；圣人不仁，以百姓为刍狗。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天地之间，其犹橐龠乎？虚而不屈，动而愈出。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "多言数穷，不如守中。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "谷神不死，是谓玄牝。玄牝之门，是谓天地之根。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "绵绵若存，用之不勤。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天长地久。天地所以能长且久者，以其不自生，故能长生。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人后其身而身先，外其身而身存。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "非以其无私邪？故能成其私。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "上善若水。水善利万物而不争，处众人之所恶，故几于道。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "居善地，心善渊，与善仁，言善信，政善治，事善能，动善时。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯不争，故无尤。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "持而盈之，不如其已。揣而锐之，不可长保。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "金玉满堂，莫之能守。富贵而骄，自遗其咎。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "功遂身退，天之道。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "载营魄抱一，能无离乎？专气致柔，能婴儿乎？", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "涤除玄览，能无疵乎？爱民治国，能无智乎？", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大方无隅；大器晚成；大音希声；大象无形。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "合抱之木，生于毫末；九层之台，起于累土。千里之行，始于足下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "五色令人目盲；五音令人耳聋；五味令人口爽；驰骋畋猎令人心发狂；难得之货令人行妨。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人为腹不为目，故去彼取此。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "宠辱若惊，贵大患若身。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "何谓宠辱若惊？宠为上辱为下，得之若惊，失之若惊，是谓宠辱若惊。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "何谓贵大患若身？吾所以有大患者，为吾有身，及吾无身，吾有何患？", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故贵以身为天下，若可寄天下；爱以身为天下，若可托天下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "视之不见曰夷；听之不闻曰希；搏之不得曰微。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "此三者不可致诘，故混而为一。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是谓无状之状，无物之象，是谓惚恍。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "迎之不见其首，随之不见其后。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "执古之道，以御今之有，能知古始。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是谓道纪。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "古之善为道者，微妙玄通，深不可识。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "豫兮，若冬涉川；犹兮，若畏四邻；俨兮，其若客；涣兮，其若凌释；敦兮，其若朴；旷兮，其若谷；混兮，其若浊。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "孰能浊以止？静之徐清；孰能安以久？动之徐生。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "保此道者不欲盈。夫唯不盈故能蔽而新成。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "致虚极，守静笃。万物并作，吾以观复。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫物芸芸，各复归其根。归根曰静，静曰复命。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "复命曰常，知常曰明。不知常，妄作，凶。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知常容，容乃公，公乃王，王乃天，天乃道，道乃久，殁身不殆。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "太上，不知有之；其次，亲而誉之；其次，畏之；其次，侮之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "悠兮其贵言。功成事遂，百姓皆谓：“我自然”。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大道废，有仁义；智慧出，有大伪；六亲不和，有孝慈；国家昏乱，有忠臣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "绝圣弃智，民利百倍；绝仁弃义，民复孝慈；绝巧弃利，盗贼无有。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故令有所属：见素抱朴，少私寡欲，绝学无忧。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "唯之与阿，相去几何？善之与恶，相去若何？", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "人之所畏，不可不畏。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "众人熙熙，如享太牢，如春登台。我独泊兮，其未兆，如婴儿之未孩。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "众人皆有馀，而我独若遗。我愚人之心也哉，沌沌兮。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "俗人昭昭，我独昏昏；俗人察察，我独闷闷。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "澹兮其若海，辽兮若无止。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "我独异于人，而贵食母。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "孔德之容，惟道是从。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道之为物，惟恍惟惚。惚兮恍兮，其中有象；恍兮惚兮，其中有物。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "窈兮冥兮，其中有精，其精甚真，其中有信。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "自今及古，其名不去，以阅众甫。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "曲则全，枉则直；洼则盈，敝则新；少则得，多则惑。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人抱一为天下式：不自见，故明；不自是，故彰；不自伐，故有功；不自矜，故长。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯不争，故天下莫能与之争。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "希言自然。故飘风不终朝，骤雨不终日。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "孰为此者？天地。天地尚不能久，而况于人乎？", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故从事于道者，道者同于道；德者同于德；失者同于失。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "企者不立；跨者不行；自见者不明；自是者不彰；自伐者无功；自矜者不长。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "其在道也，曰馀食赘形，物或恶之，故有道者不处。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "有物混成，先天地生。寂兮寥兮，独立而不改，周行而不殆，可以为天地母。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "吾不知其名，字之曰道，强为之名曰大。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大曰逝，逝曰远，远曰反。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故道大，天大，地大，王亦大。域中有四大，而王居其一焉。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "人法地，地法天，天法道，道法自然。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "重为轻根，静为躁君。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人终日行不离辎重。虽有荣观，燕处超然。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "奈何万乘之主，而以身轻天下？轻则失本，躁则失君。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "善行，无辙迹；善言，无瑕谪；善数，不用筹策；善闭，无关楗而不可开；善结，无绳约而不可解。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人常善救人，故无弃人；常善救物，故无弃物。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是谓袭明。故善人者不善人之师；不善人者善人之资。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "不贵其师，不爱其资，虽智大迷。是谓要妙。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知其雄，守其雌，为天下溪。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "为天下溪，常德不离，复归于婴儿。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知其白，守其黑，为天下式。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "为天下式，常德不忒，复归于无极。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知其荣，守其辱，为天下谷。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "为天下谷，常德乃足，复归于朴。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故大制无割。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "将欲取天下而为之，吾见其不得已。天下神器，不可为也。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "为者败之，执者失之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故物或行或随，或嘘或吹，或强或羸，或挫或隳。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人去甚去奢去泰。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "以道佐人主者，不以兵强天下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "其事好还：师之所居，荆棘生焉；大军之后，必有凶年。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "善有果而已，不敢以取强。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "果而勿矜，果而勿伐，果而勿骄，果而不得已，果而勿强。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "物壮则老，是谓不道，不道早已。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯兵者，不祥之器，物或恶之，故有道者不处。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "君子居则贵左，用兵则贵右。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "兵者不祥之器，非君子之器，不得已而用之，恬淡为上。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "胜而不美，而美之者，是乐杀人。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫乐杀人者则不可得志于天下矣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "吉事尚左，凶事尚右。偏将军居左，上将军居右，言以丧礼处之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "杀人之众，以悲哀莅之，战胜以丧礼处之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道常无名。朴虽小，天下莫能臣也。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "侯王若能守之，万物将自宾。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天地相合，以降甘露，民莫之令，而自均。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "始制有名，名亦既有，夫亦将知止。知止可以不殆。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "譬道之在天下，犹川谷之于江海。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知人者智，自知者明；胜人者有力，自胜者强。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知足者富。强行者有志。不失其所者久，死而不亡者寿。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大道泛兮其可左右。万物恃之而生而不辞，功成而不名有，衣养万物而不为主，常无欲。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "可名于小，万物归焉而不为主；可名为大，以其终不自为大，故能成其大。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "执大象，天下往。往而不害，安平泰。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "乐与饵，过客止。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道之出口淡乎其无味，视之不足见，听之不足闻，用之不足既。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "将欲歙之，必固张之；将欲弱之，必固强之；将欲废之，必固兴之；将欲取之，必固与之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是谓微明。柔弱胜刚强。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "鱼不可脱于渊，国之利器不可以示人。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道常无为而不为。侯王若能守之，万物将自化。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "化而欲作，吾将镇之以无名之朴。无名之朴亦将不欲。不欲以静，天下将自定。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "上德不德，是以有德；下德不失德，是以无德。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "上德无为而无以为，下德无为而有以为。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "上仁为之而无以为；上义为之而有以为。上礼为之而莫之应，则攘臂而扔之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故失道而后德，失德而后仁，失仁而后义，失义而后礼。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫礼者，忠信之薄而乱之首。前识者，道之华而愚之始。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以大丈夫居其厚不居其薄；居其实不居其华。故去彼取此。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "昔之得一者：天得一以清；地得一以宁；神得一以灵；谷得一以盈；万物得一以生；侯得一以为天下正。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "其致之，天无以清，将恐裂；地无以宁，将恐废；神无以灵，将恐歇；谷无以盈，将恐竭；万物无以生，将恐灭；侯王无以贵高，将恐蹶。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故贵以贱为本，高以下为基。是以侯王自谓“孤”、“寡”、“不谷”。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "此非以贱为本耶？非乎？故致数誉无誉。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是故不欲禄禄如玉，珞珞如石。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "反者道之动，弱者道之用。天下万物生于有，有生于无。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "上士闻道，勤而行之；中士闻道，若存若亡；下士闻道，大笑之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "不笑，不足以为道。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故建言有之﹕明道若昧，进道若退，夷道若纇，上德若谷，大白若辱，廣德若不足，建德若偷，質真若渝，大方無隅，大器晚成，大音希聲，大象無形，道隱無名。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯道，善貸且成。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道生一，一生二，二生三，三生萬物。萬物負陰而抱陽，沖氣以為和。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "人之所惡，唯孤﹑寡﹑不穀，而王公以為稱。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故物或損之而益，或益之而損。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "人之所教，我亦教之。強梁者不得其死，吾將以為教父。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下之至柔，馳騁天下之至堅。無有入無閒，吾是以知無為之有益。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "不言之教，無為之益，天下希及之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "名與身孰親﹖身與貨孰多﹖得與亡孰病﹖", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是故甚愛必大費，多藏必厚亡。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知足不辱，知止不殆，可以長久。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大成若缺，其用不弊。大盈若沖，其用不窮。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大直若屈，大巧若拙，大辯若訥。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "靜勝躁，寒勝熱。清靜為天下正。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下有道，卻走馬以糞。天下無道，戎馬生於郊。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "禍莫大於不知足；咎莫大於欲得。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故知足之足，常足矣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "不出戶，知天下；不窺牖，見天道。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "其出彌遠，其知彌少。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以聖人不行而知，不見而明，不為而成。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "為學日益，為道日損。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "損之又損，以至於無為。無為而無不為。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "取天下常以無事，及其有事，不足以取天下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "聖人無常心，以百姓心為心。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "善者，吾善之；不善者，吾亦善之；德善。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "信者，吾信之；不信者，吾亦信之；德信。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "聖人在，天下歙歙焉，為天下渾其心，百姓皆注其耳目，聖人皆孩之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "出生入死。生之徒，十有三；死之徒，十有三；人之生，動之死地，亦十有三。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫何故﹖以其生生之厚。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "蓋聞善攝生者，陸行不遇兕虎，入軍不被甲兵；兕無所投其角，虎無所措其爪，兵無所容其刃。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫何故﹖以其無死地。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道生之，德畜之，物形之，勢成之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以萬物莫不尊道而貴德。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道之尊，德之貴，夫莫之命而常自然。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故道生之，德畜之。長之育之，亭之毒之，養之覆之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "生而不有，為而不恃，長而不宰。是謂玄德。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下有始，以為天下母。既得其母，以知其子，既知其子，復守其母，沒身不殆。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "塞其兌，閉其門，終身不勤。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "開其兌，濟其事，終身不救。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "見小曰明，守柔曰強。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "用其光，復歸其明，無遺身殃，是為習常。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "假如我介然有知，行于大道，唯施是畏。大道甚夷，而人好徑。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "朝甚除，田甚蕪，倉甚虛；服文綵，帶利劍，厭飲食，財貨有餘；是為夸盜。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "非道也哉﹗", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "善建者不拔，善抱者不脫，子孫以祭祀不輟。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "修之於身，其德乃真；修之於家，其德乃餘；修之於鄉，其德乃長；修之於國，其德乃豐；修之于天下，其德乃普。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故以身觀身，以家觀家，以鄉觀鄉，以國觀國，以天下观天下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "吾何以知天下然哉﹖以此。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "含德之厚，比於赤子。蜂蠆虺蛇不螫，猛獸不據，攫鳥不搏。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "骨弱筋柔而握固。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "未知牝牡之合而全作，精之至也。終日號而不嗄，和之至也。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知和曰常，知常曰明。益生曰祥。心使氣曰強。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "物壯則老，謂之不道，不道早已。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知者不言，言者不知。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "塞其兌，閉其門，挫其銳，解其分，和其光，同其塵。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是謂玄同。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故不可得而親，不可得而疏；不可得而利，不可得而害；不可得而貴，不可得而賤。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故為天下貴。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "以正治國，以奇用兵，以無事取天下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "吾何以知其然哉﹖以此。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下多忌諱，而民彌貧；民多利器，國家滋昏；人多伎巧，奇物滋起；法令滋彰，盜賊多有。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故聖人云﹕「我無為，而民自化；我好靜，而民自正；我無事，而民自富；我無欲，而民自樸。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "其政悶悶，其民淳淳；其政察察，其民缺缺。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "禍兮福之所倚，福兮禍之所伏。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "孰知其極﹖其無正。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "正復為奇，善復為妖。人之迷，其日固久。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以聖人方而不割，廉而不劌，直而不肆，光而不燿。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "治人事天，莫若嗇。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯嗇，是謂早服；早服謂之重積德；重積德則無不克；無不克則莫知其極；莫知其極，可以有國；有國之母，可以長久；是謂深根固柢，長生久視之道。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "治大國，若烹小鮮。以道蒞天下，其鬼不神；非其鬼不神，其神不傷人；非其神不伤人，圣人亦不伤人。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫兩不相傷，故德交歸焉。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大國者下流，天下之交。天下之牝，牝常以靜勝牡，以靜為下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故大國以下小國，則取小國；小國以下大國，則取大國。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故或下以取，或下而取。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "大國不過欲兼畜人，小國不過欲入事人。夫兩者各得其所欲，大者宜為下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "道者萬物之奧。善人之寶，不善人之所保。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "美言可以市，尊行可以加人。人之不善，何弃之有﹖", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故立天子，置三公，雖有拱璧以先駟馬，不如坐進此道。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "古之所以貴此道者何﹖不曰﹕以求得，有罪以免邪﹖故為天下貴。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "為無為，事無事，味無味。大小多少，報怨以德。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "圖難於其易，為大於其細；天下難事必作於易，天下大事必作於細。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以聖人終不為大，故能成其大。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫輕諾必寡信，多易必多難。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以聖人猶難之，故終無難矣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "其安易持，其未兆易謀。其脆易泮，其微易散。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "為之於未有，治之於未亂。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "為者敗之，執者失之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人无为故无败，无执故无失。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "民之从事，常于几成而败之。慎终如始，则无败事。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人欲不欲，不贵难得之货；学不学，复众人之所过。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "以辅万物之自然，而不敢为。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "古之善為道者，非以明民，将以愚之。民之难治，以其智多。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故以智治国，国之贼；不以智治国，国之福。知此两者亦稽式。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "常知稽式，是谓玄德。玄德深矣，远矣，与物反矣，然後乃至大顺。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "江海所以能为百谷王者，以其善下之，故能为百谷王。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以欲上民，必以言下之。欲先民，必以身後之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人处上而民不重，处前而民不害。是以天下乐推而不厌，以其不争，故天下莫能与之争。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下皆谓我道大，似不肖。夫唯大，故似不肖。若肖，久矣其细也夫﹗", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "我有三宝，持而保之。一曰慈，二曰俭，三曰不敢为天下先。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "慈故能勇；俭故能广；不敢为天下先，故能成器长。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "今舍慈且勇，舍俭且广，舍后且先，死矣﹗", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫慈以战则胜，以守则固。天将救之，以慈卫之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "善为士者不武，善战者不怒，善胜敌者不与，善用人者为其下，是谓不争之德，是谓用人之力，是谓配天古之极。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "用兵有言﹕「吾不敢为主而为客，不敢进寸而退尺。」", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是谓行无行，攘无臂，扔无敌，执无兵。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "祸莫大於轻敌，轻敌几丧吾宝。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故抗兵相加，哀者胜矣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "吾言甚易知，甚易行。天下莫能知，莫能行。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "言有宗，事有君。夫唯无知，是以不我知。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知我者希，则我者贵。是以圣人被褐怀玉。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "病病，是以不病。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "民不畏威，则大威至。无狎其所居，无厌其所生。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯不厌，是以不厌。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人自知不自见；自爱不自贵。故去彼取此。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "勇于敢则杀，勇于不敢则活。此两 Dì, 或利或害。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天之所恶，孰知其故？是以圣人犹难之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天之道，不争而善胜，不言而善应，不召而自来，繟然而善谋。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天网恢恢，疏而不失。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "民不畏死，奈何以死惧之？", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "若使民常畏死，而为奇者，吾得执而杀之，孰敢？常有司杀者杀。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫代司杀者杀，是谓代大匠斲，夫代大匠斲者，希有不伤其手矣。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "民之饥，以其上食税之多，是以饥。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "民之难治，以其上之有为，是以难治。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "民之轻死，以其求生之厚，是以轻死。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "夫唯无以生为者，是贤于贵生。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "人之生也柔弱，其死也坚强。万物草木之生也柔脆，其死也枯槁。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "故坚强者死之徒，柔弱者生之徒。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以兵强则不胜，木强则兵。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "强 H处下，柔弱处上。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天之道，其犹张弓与﹖高者抑之，下者举之；有馀者损之，不足者补之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天之道，损有馀而补不足。人之道则不然，损不足以奉有馀。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "孰能有馀以奉天下，唯有道者。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人为而不恃，功成而不处，其不欲见贤。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天下莫柔弱於水，而攻坚强者莫之能胜，以其无以易之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "弱之胜强，柔之胜刚，天下莫不知莫能行。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人云﹕「受国之垢，是谓社稷主；受国不祥，是为天下王。」", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "正言若反。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "和大怨，必有馀怨，安可以为善﹖", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "是以圣人执左契，而不责於人。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "有德司契，无德司彻。天道无亲，常与善人。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "小国寡民。使有什伯之器而不用，使民重死而不远徙。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "虽有舟舆，无所乘之，虽有甲兵，无所陈之。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "使人复结绳而用之，甘其食，美其服，安其居，乐其俗。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "邻国相望，鸡犬之声相闻，民至老死，不相往来。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "信言不美，美言不信。善者不辩，辩者不善。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "知者不博，博者不知。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "圣人不积，既以为人己愈有，既以与人己愈多。", Author = "老子" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/老子", Text = "天之道，利而不害；圣人之道，为而不争。", Author = "老子" },
        };
    }
}